import numpy as np

def gini(c):
    p = np.array(c, dtype=float) / np.sum(c)
    return 1.0 - np.sum(p ** 2)

def entropy(c):
    p = np.array(c, dtype=float) / np.sum(c)
    p = p[p > 0]
    return -np.sum(p * np.log2(p))

# Split A: [40,0] & [10,50] vs Split B: [46,4] & [4,46] (Parent=[50,50])
wg_A, wg_B = 0.4 * gini([40, 0]) + 0.6 * gini([10, 50]), 0.5 * gini([46, 4]) + 0.5 * gini([4, 46])
we_A, we_B = 0.4 * entropy([40, 0]) + 0.6 * entropy([10, 50]), 0.5 * entropy([46, 4]) + 0.5 * entropy([4, 46])
assert wg_B < wg_A and we_A < we_B  # Gini prefers B, Entropy prefers A!
print(f'Gini: A={wg_A:.4f} vs B={wg_B:.4f} | Entropy: A={we_A:.4f} vs B={we_B:.4f}')
